va_list args;
va_start(args, fixed);
Type val = va_arg(args, Type);
va_end(args);

example:
#include <stdarg.h>
#include <stdio.h>

int sum(int count, ...) {
    va_list args;
    va_start(args, count);
    int total = 0;
    for (int i = 0; i < count; i++) {
        total += va_arg(args, int);
    }
    va_end(args);
    return total;
}

printf("%d\n", sum(3, 10, 20, 30)); // 60

