syntax:
[[deprecated("reason")]] ReturnType func(...);
[[maybe_unused]] Type var;
[[nodiscard]] ReturnType func(...);
case X: stmt; [[fallthrough]];

example:
#include <stdio.h>

[[nodiscard]] int mustCheck(void) { return 42; }

int main(void) {
    int x = 1;
    switch (x) {
        case 1:
            printf("واحد\n");
            [[fallthrough]];
        case 2:
            printf("أو اثنين\n");
            break;
    }
    int v = mustCheck();   // لو تجاهلت القيمة، المترجم يحذّر
    printf("%d\n", v);
    return 0;
}

syntax:
struct Name {
    size_t count;
    Type items[] __attribute__((counted_by(count)));
};

example:
#include <stdio.h>
#include <stdlib.h>

struct Buffer {
    size_t count;
    int items[] __attribute__((counted_by(count)));
};

int main(void) {
    size_t n = 3;
    struct Buffer *b = malloc(sizeof(struct Buffer) + n * sizeof(int));
    b->count = n;   // لازم تحديثه فورًا بعد التخصيص

    for (size_t i = 0; i < b->count; i++) {
        b->items[i] = (int)i * 10;
    }
    printf("%d\n", b->items[2]);   // 20

    // b->items[5] = 1;   // خارج الحدود: يُكتشف وقت التشغيل مع -fsanitize=array-bounds

    free(b);
    return 0;
}
